def histogram(test):
    # Convert test string to lowercase and split it into individual letters
    letters = test.lower().split()

    # Create an empty dictionary to store the count of each letter
    count_dict = {}

    # Iterate through each letter in the list of letters
    for letter in letters:
        # If the letter is not already in the count_dict, add it with a value of 1
        if letter not in count_dict:
            count_dict[letter] = 1
        # If the letter is already in the count_dict, increment its value by 1
        else:
            count_dict[letter] += 1

    # Return the count_dict as a dictionary of letters and their corresponding counts
    return dict(count_dict)
