def do_algebra(operator, operand):
    assert len(operator) == len(operand)-1, "Error: Length of operator and operand lists must be equal except for the last element."
    result = 0
    for i in range(len(operand)):
        if operator[i] == '+':
            result += operand[i]
        elif operator[i] == '-':
            result -= operand[i]
        elif operator[i] == '*':
            result *= operand[i]
        elif operator[i] == '/':
            result /= operand[i]
        elif operator[i] == '**':
            result **= operand[i]
    return result
